  'phase.1.question': 'Are we ready to co-design, and on what terms?',
  'phase.1.outcome': 'An agreed process frame covering participation ambition, decision boundaries, relevant actors, and organisational conditions.',
  'phase.2.question': 'How do different actors understand the place and its challenges?',
  'phase.2.outcome': 'A shared diagnosis of needs, qualities, conflicts, opportunities, and priority challenges from multiple perspectives.',
  'phase.3.question': 'What futures are possible and desirable?',
  'phase.3.outcome': 'Co-developed scenarios, concepts, or design principles that respond to the shared diagnosis and NEB values.',
  'phase.4.question': 'What happens if we try this, even temporarily?',
  'phase.4.outcome': 'Situated evidence that supports the revision, validation, combination, or rejection of proposed solutions.',
  'phase.5.question': 'What stays, who takes care of it, and what did we learn?',
  'phase.5.outcome': 'Agreed next steps, governance or stewardship arrangements, documented learning, and a clear route into future action.',
  'privacy.languageLabel': 'Policy language',
  'privacy.eyebrow': 'Trust and transparency',
  'privacy.title': 'Privacy Policy',
  'privacy.updated': 'Updated July 7, 2026',
  'privacy.intro': 'This Privacy Policy explains how the SPICE Digital Toolkit collects, uses, shares, and protects personal data when citizens, municipalities, facilitators, and project partners use the platform.',
  'privacy.contextNotice': 'SPICE may also show contextual privacy notices inside specific tools and account settings, so people understand what data is requested before they contribute.',
  'privacy.readPolicy': 'Read the policy',
  'privacy.download': 'Download a copy',
  'privacy.cookiePreferences': 'Cookie preferences',
  'privacy.dataPrivacy': 'Data and privacy',
  'privacy.participantFirst': 'Participant-first',
  'privacy.participantFirstText': 'The toolkit supports civic participation. Contributions are handled with respect, transparency, and a clear, limited purpose.',
  'privacy.policyHeadings': 'Policy headings',
  'privacy.contextualText': 'SPICE keeps privacy information practical and contextual. When a tool requests a contribution, upload, location, or account action, it explains why the data is needed and how it supports co-creation.',
  'privacy.helpTitle': 'Need help with a privacy request?',
  'privacy.helpText': 'Contact your pilot facilitator or SPICE project contact with the email address used for your account, your pilot site, and the request type. The request will be routed to the appropriate responsible organisation.',
  'privacy.section.overview.title': 'Privacy overview',
  'privacy.section.overview.text': 'SPICE supports inclusive public-space co-creation while limiting personal data collection to what is needed for participation, security, and project reporting.',
  'privacy.section.collection.title': 'Personal data we collect',
  'privacy.section.collection.text': 'We may collect account details, pilot affiliation, language and accessibility preferences, participation, map feedback, votes, uploaded media, comments, and technical usage information.',
  'privacy.section.use.title': 'How we use personal data',
  'privacy.section.use.text': 'Data is used to operate the platform, support participation, produce co-creation outputs, improve accessibility, prevent misuse, and provide structured, aggregated insights.',
  'privacy.section.sharing.title': 'Sharing and project partners',
  'privacy.section.sharing.text': 'Relevant project data may be shared with authorised SPICE partners, pilot municipalities, facilitators, and technical providers where necessary for the co-creation process.',
  'privacy.section.cookies.title': 'Cookies and similar technologies',
  'privacy.section.cookies.text': 'Essential cookies keep the toolkit secure and functional. Optional analytics cookies help improve workflows, performance, multilingual support, and accessibility.',
  'privacy.section.rights.title': 'Your privacy rights',
  'privacy.section.rights.text': 'Depending on your location, you may request access, correction, deletion, restriction, portability, or object to the processing of your personal data.',
  'privacy.section.security.title': 'Protection of personal data',
  'privacy.section.security.text': 'SPICE uses role-based access, secure operations, data minimisation, and responsible retention practices to protect participant contributions.',
  'privacy.section.contact.title': 'Privacy questions',
  'privacy.section.contact.text': 'For privacy questions or requests, contact the SPICE project team or the responsible pilot organisation listed in your local participation materials.',
  'guide.title': 'Co-Creation Guide',
  'guide.subtitle': 'Guided support for tool selection and process structuring',
