  'home.tool.processText': 'Ανακαλύψτε πιλοτικές τοποθεσίες, συμμετάσχετε σε ανοιχτές δραστηριότητες και διαχειριστείτε το ταξίδι από έναν κεντρικό κόμβο.',
  'home.tool.sceneText': 'Επεξεργαστείτε, οπτικοποιήστε και συγκρίνετε σενάρια δημόσιου χώρου σε ένα τρισδιάστατο περιβάλλον.',
  'home.tool.aiTitle': 'AI Chatbot',
  'home.tool.aiText': 'Λάβετε σαφείς οδηγίες και απαντήσεις για συγκεκριμένο έργο με βάση πόρους και έγγραφα SPICE.',
  'home.tool.citivoiceTitle': 'Εφαρμογή CitiVoice',
  'home.tool.citivoiceText': 'Συλλέξτε σχόλια γεωγραφικής τοποθεσίας, φωτογραφίες, ψήφους και τοπικές προτεραιότητες.',
  'home.tool.repositoryText': 'Πρόσβαση σε πιλοτικά έγγραφα, αποτελέσματα εργαστηρίου, αναφορές, μέσα, πρότυπα και αποτελέσματα συνδημιουργίας σε έναν οργανωμένο χώρο.',
  'home.tool.forumText': 'Συζητήστε ιδέες, ανταλλάξτε απόψεις, σχολιάστε προτάσεις και συμμετάσχετε σε έρευνες και δραστηριότητες ψηφοφορίας.',
  'home.tool.insightsText': 'Παρακολουθήστε τη συμμετοχή, τα μοτίβα σχολίων, τα αποτελέσματα και την πρόοδο του πιλότου.',
  'home.feature.localized': 'Τοπική διεπαφή',
  'home.feature.localizedText': 'Πλοήγηση, φόρμες, οδηγίες και ειδοποιήσεις προσαρμοσμένες σε κάθε γλώσσα πιλότου.',
  'home.feature.guidance': 'Διαγραφή καθοδήγησης',
  'home.feature.guidanceText': 'Σύντομες επεξηγήσεις και βήμα προς βήμα υποστήριξη για χρήστες για πρώτη φορά και μη ειδικούς.',
  'home.feature.participation': 'Συμμετοχή χωρίς αποκλεισμούς',
  'home.feature.participationText': 'Οι συμμετέχοντες μπορούν να κατανοήσουν, να συνεισφέρουν, να ψηφίσουν και να παρακολουθήσουν τα αποτελέσματα σε μια οικεία γλώσσα.',
  'home.feature.content': 'Περιεχόμενο έτοιμο για πιλότο',
  'home.feature.contentText': 'Οι σελίδες του έργου, οι φόρμες σχολίων, οι περιλήψεις και το υλικό μπορούν να προσαρμοστούν τοπικά για κάθε πόλη.',
  'hub.eyebrow': 'Ψηφιακή εργαλειοθήκη SPICE',
  'hub.title': 'Κόμβος συν-δημιουργίας',
  'hub.subtitle': 'Λάβετε μέρος σε τοπικούς πιλοτικούς ιστότοπους συν-δημιουργίας, συνεισφέρετε σε ανοιχτές δραστηριότητες και παρακολουθήστε πώς τα στοιχεία της κοινότητας διαμορφώνουν τις αποφάσεις για τον δημόσιο χώρο.',
  'hub.subtitleCitizen': 'Λάβετε μέρος σε τοπικούς πιλοτικούς ιστότοπους συν-δημιουργίας, συνεισφέρετε σε ανοιχτές δραστηριότητες και παρακολουθήστε πώς τα στοιχεία της κοινότητας διαμορφώνουν τις αποφάσεις για τον δημόσιο χώρο.',
  'hub.subtitleMunicipality': 'Διαχειριστείτε τις φάσεις, τα εργαλεία και τη συμμετοχή του πιλοτικού ιστότοπού σας και ελέγξτε τις συνεισφορές των πολιτών.',
  'hub.subtitleFacilitator': 'Υποστηρίξτε τον πιλοτικό ιστότοπο που σας έχει ανατεθεί: προετοιμάστε δραστηριότητες, μεταφορτώστε αποτελέσματα εργαστηρίου και προσχέδια προτάσεων για έλεγχο του δήμου.',
  'hub.subtitleAdmin': 'Ελέγξτε κάθε πιλοτικό ιστότοπο συν-δημιουργίας στην πλατφόρμα και ανοίξτε την περιοχή διαχείρισης για χρήστες, ρόλους και δραστηριότητα ελέγχου.',
