  'hub.confirmPhaseForwardTitle': 'Αλλαγή τρέχουσας φάσης;',
  'hub.confirmPhaseForwardBody': 'Η φάση {{phase}} θα γίνει η τρέχουσα φάση. Οι φάσεις {{completedList}} θα επισημανθούν ως ολοκληρωμένες, ενώ οι φάσεις {{incompleteList}} θα παραμείνουν ελλιπείς.',
  'hub.confirmPhaseBackwardTitle': 'Επιστροφή σε προηγούμενη φάση;',
  'hub.confirmPhaseBackwardBody': 'Η φάση {{phase}} θα γίνει η τρέχουσα φάση. Οι μεταγενέστερες φάσεις θα επισημανθούν ως ελλιπείς. Οποιαδήποτε μη δημοσιευμένη διαμόρφωση για αυτές τις φάσεις θα διατηρηθεί, αλλά δεν θα είναι πλέον ενεργή.',
