  'hub.dashboardIntroCitizen': 'Ακολουθήστε το τοπικό σας ταξίδι συνδημιουργίας, λάβετε μέρος σε ανοιχτές δραστηριότητες και εξερευνήστε δημοσιευμένα εργαλεία και αποτελέσματα.',
