  'hub.publicForum': 'Προβολή δημόσιων συζητήσεων',
  'hub.publicForumText': 'Διαβάστε τις προτάσεις της κοινότητας, τις προτεραιότητες και τις απαντήσεις του δήμου πριν συμμετάσχετε στη συζήτηση.',
  'hub.publicPilots': 'Ανακαλύψτε τους πιλοτικούς ιστότοπους',
  'hub.publicPilotsText': 'Εξερευνήστε τα τέσσερα ευρωπαϊκά πιλοτικά πλαίσια και τις προκλήσεις του δημόσιου χώρου που αντιμετωπίζουν οι κοινότητές τους.',
  'hub.publicExplore': 'Εξερεύνηση',
  'hub.accountTitle': 'Δημιουργήστε τον λογαριασμό συνδημιουργίας σας',
  'hub.accountText': 'Εγγραφείτε ή συνδεθείτε για να δείτε τους διαθέσιμους πιλοτικούς ιστότοπους και λάβετε μέρος μόλις ανοίξουν οι δραστηριότητες.',
  'hub.accountBenefitsTitle': 'Με έναν λογαριασμό μπορείτε',
  'hub.accountBenefit1': 'Δείτε τον διαθέσιμο πιλοτικό ιστότοπο συν-δημιουργίας.',
  'hub.accountBenefit2': 'Λάβετε μέρος σε ανοιχτές δραστηριότητες ενώ εκτελούνται.',
  'hub.accountBenefit3': 'Ακολουθήστε ενημερώσεις φάσης, δημοσιευμένα αποτελέσματα και ειδοποιήσεις.',
  'hub.accountBenefit4': 'Υποβάλετε προτάσεις, συμμετάσχετε σε συζητήσεις και ψηφίστε στη Συζήτηση και Απόφαση.',
  'process.title': 'Επιλέξτε πώς θέλετε να ξεκινήσετε',
  'process.subtitle': 'Ξεκινήστε το ταξίδι συνδημιουργίας σας με τον τρόπο που ταιριάζει καλύτερα στις ανάγκες σας.',
  'process.question': 'Γιατί είσαι εδώ;',
  'process.setup': 'Για να ρυθμίσω τη διαδικασία μου',
  'process.setupText': 'Ορίστε τη δραστηριότητά σας, επιλέξτε το πιλοτικό πλαίσιο, προσκαλέστε συμμετέχοντες και οργανώστε τα βήματα από τη συλλογή ιδεών έως τα κοινά αποτελέσματα.',
  'process.explore': 'Εξερευνήστε ελεύθερα την εργαλειοθήκη',
  'process.exploreText': 'Περιηγηθείτε στα διαθέσιμα εργαλεία SPICE, πόρους, χάρτες, εξόδους αποθετηρίου και δυνατότητες συμμετοχής με τον δικό σας ρυθμό.',
  'process.scenarios': 'Δείτε πιλοτικά σενάρια',
  'process.scenariosText': 'Τα σενάρια τεκμηριώνουν τον τρόπο με τον οποίο εφαρμόστηκε η προσέγγιση συν-δημιουργίας στις τέσσερις πιλοτικές τοποθεσίες SPICE. Δημοσιεύονται σταδιακά καθώς ολοκληρώνονται οι πιλότοι.',
  'process.chatbot': 'Ρωτήστε το AI Chatbot',
  'process.chatbotText': 'Λάβετε γρήγορη καθοδήγηση σχετικά με τη διαδικασία συν-δημιουργίας, τις λειτουργίες της εργαλειοθήκης, τα έγγραφα έργου και τα επόμενα βήματα.',
  'methodology.eyebrow': 'Μεθοδολογία SPICE',
  'methodology.title': 'Μεθοδολογία συνδημιουργίας για δημόσιους χώρους χωρίς αποκλεισμούς',
  'methodology.subtitle': 'Μια δομημένη διαδικασία που βοηθά τους πιλότους να περάσουν από την κοινή κατανόηση σε πρακτικές επιλογές σχεδίασης, σχόλια, τεκμηρίωση και υποστήριξη αποφάσεων.',
  'methodology.openGuide': 'Ανοίξτε τον Οδηγό συν-δημιουργίας',
  'methodology.phase1': 'Καδράρισμα και ετοιμότητα',
  'methodology.phase1Text': 'Ορίστε την τοπική πρόκληση, χαρτογραφήστε τα ενδιαφερόμενα μέρη, ελέγξτε την ετοιμότητα και επιλέξτε τη σωστή ρύθμιση συμμετοχής για το πιλότο.',
  'methodology.phase2': 'Συλλογική κατανόηση',
  'methodology.phase2Text': 'Συλλέξτε τοπικές γνώσεις μέσα από χάρτες, περιπάτους, έρευνες, εργαστήρια, σχόλια και κοινές παρατηρήσεις.',
  'methodology.phase3': 'Σχεδιασμός σεναρίου',
  'methodology.phase3Text': 'Μετατρέψτε τις εισροές σε επιλογές σχεδίασης, συγκρίνετε εναλλακτικές και συζητήστε συμβιβασμούς με πολίτες και ομάδες σχεδιασμού.',
  'methodology.phase4': 'Υποστήριξη αποφάσεων',
  'methodology.phase4Text': 'Συνοψίστε τα αποτελέσματα, μοιραστείτε στοιχεία, τεκμηριώστε αποφάσεις και κρατήστε την κοινότητα ενήμερη μετά τη συμμετοχή.',
  'methodology.phase5': 'Ενοποίηση και εκμάθηση',
  'methodology.phase5Text': 'Αξιολογήστε τη διαδικασία, επισημοποιήστε τις ευθύνες, διατηρήστε τα αποτελέσματα και λάβετε μαθήματα για μελλοντικές αποφάσεις.',
  'methodology.used': 'Πώς χρησιμοποιείται η μέθοδος',
  'methodology.used1': 'Μετατρέπει τους στόχους ευρείας συμμετοχής σε μια σαφή ακολουθία φάσεων, εργαλείων, δραστηριοτήτων, αποτελεσμάτων και σημείων λήψης αποφάσεων.',
  'methodology.used2': 'Οι δήμοι και οι διαμεσολαβητές μπορούν να προγραμματίσουν εργαστήρια, να επιλέξουν κατάλληλα εργαλεία, να θέτουν προσδοκίες και να εξηγήσουν γιατί κάθε δραστηριότητα έχει σημασία.',
  'methodology.used3': 'Αποτελέσματα εργαστηρίου, σχόλια CitiVoice, τρισδιάστατα σενάρια και έγγραφα αποθήκης παραμένουν συνδεδεμένα μεταξύ των δραστηριοτήτων.',
  'methodology.used4': 'Η εισαγωγή πολιτών γίνεται δομημένα αποτελέσματα μέσω χαρτογράφησης, ομαδοποίησης, ψηφοφορίας, περιλήψεων, αναφορών και επακόλουθων ενεργειών.',
  'methodology.evidence': 'Πηγές αποδεικτικών στοιχείων',
