  'demo.guideText': 'Μια πρακτική διαδρομή μέσω της πλατφόρμας SPICE.',
  'demo.chooseRoleGuide': 'Επιλέξτε οδηγό ρόλου',
  'demo.chooseRoleGuideText': 'Δείτε τις ευθύνες κάθε ρόλου, τα σημεία παράδοσης της εργασίας και ποιο τμήμα της πλατφόρμας υποστηρίζει κάθε βήμα.',
  'demo.platformGuideTitle': 'Βασικές λειτουργίες της πλατφόρμας',
  'demo.platformGuideText': 'Χρησιμοποιήστε αυτούς τους σύντομους οδηγούς για να βρείτε τους πιλοτικούς χώρους, τις ενέργειες και τα δημοσιευμένα τεκμήρια που αφορούν τον επιλεγμένο ρόλο.',
  'demo.step1': 'Επιλέξτε το πιλοτικό σας πλαίσιο',
  'demo.step1Text': 'Ξεκινήστε με τη σελίδα Pilot Sites και, στη συνέχεια, δημιουργήστε έναν λογαριασμό συνδεδεμένο με το μέρος όπου θέλετε να συμμετάσχετε.',
  'demo.step2': 'Ρυθμίστε μια διαδικασία συνδημιουργίας',
  'demo.step2Text': 'Ορίστε τη φάση, τους στόχους, τη μορφή δραστηριότητας, τον διαθέσιμο χρόνο και το πλαίσιο διευκόλυνσης. Η SPICE συνιστά κατάλληλα εργαλεία.',
  'demo.step3': 'Συμβάλετε και παρακολουθήστε την πρόοδο',
  'demo.step3Text': 'Χρησιμοποιήστε το CitiVoice, το φόρουμ, τα εργαστήρια και τα τρισδιάστατα σενάρια για να προσθέσετε στοιχεία και ιδέες. Οι ειδοποιήσεις σας κρατούν ενήμερους.',
  'demo.step4': 'Βρείτε αποτελέσματα και αποτελέσματα',
  'demo.step4Text': 'Χρησιμοποιήστε τις σελίδες Αποθετήριο και Insights για να ελέγξετε τα αποτελέσματα του εργαστηρίου, τα μοτίβα σχολίων, τα έγγραφα και τα πιλοτικά αποτελέσματα.',
  'demo.keyboardText': 'Χρησιμοποιήστε Tab και Shift+Tab για να μετακινηθείτε στα χειριστήρια, Enter ή Space για ενεργοποίηση κουμπιών, Escape για κλείσιμο μενού και παραθύρων και την ορατή ένδειξη εστίασης για παρακολούθηση της θέσης σας.',
  'scenarios.title': 'Σενάρια',
  'scenarios.subtitle': 'Τα σενάρια SPICE θα αναπτυχθούν από την εφαρμογή της προσέγγισης συν-δημιουργίας στις τέσσερις πιλοτικές τοποθεσίες του έργου. Κάθε σενάριο θα τεκμηριώνει τα εργαλεία που χρησιμοποιούνται, τις δραστηριότητες που πραγματοποιήθηκαν, τα αποτελέσματα που προκύπτουν και τα διδάγματα.',
  'scenarios.wipLabel': 'Εργασία σε εξέλιξη',
  'scenarios.currentlyImplementing': 'Η SPICE εφαρμόζει και δοκιμάζει αυτήν τη στιγμή την προσέγγιση συν-δημιουργίας σε τέσσερις πιλοτικούς ιστότοπους. Κάθε ολοκληρωμένη πιλοτική εφαρμογή θα μετατραπεί αργότερα σε ένα τεκμηριωμένο σενάριο, το οποίο δημοσιεύεται σταδιακά καθώς ολοκληρώνονται τα πιλοτικά.',
  'scenarios.howTheyAreBuiltTitle': 'Πώς δημιουργούνται τα σενάρια',
  'scenarios.willContainTitle': 'Τι θα περιέχει κάθε σενάριο',
