  'scenarios.wipSupporting': 'Όταν είναι διαθέσιμα, αυτά τα σενάρια θα παρέχουν πρακτικά παραδείγματα που άλλοι δήμοι και πόλεις μπορούν να χρησιμοποιήσουν ως έμπνευση όταν σχεδιάζουν τα δικά τους ταξίδια συνδημιουργίας.',
