  'privacy.participantFirstText': 'Η εργαλειοθήκη υποστηρίζει τη συμμετοχή των πολιτών. Οι συνεισφορές αντιμετωπίζονται με σεβασμό, διαφάνεια και σαφή, περιορισμένο σκοπό.',
  'privacy.policyHeadings': 'Επικεφαλίδες πολιτικής',
  'privacy.contextualText': 'Το SPICE διατηρεί τις πληροφορίες απορρήτου πρακτικές και συναφείς με τα συμφραζόμενα. Όταν ένα εργαλείο ζητά μια συνεισφορά, μεταφόρτωση, τοποθεσία ή ενέργεια λογαριασμού, εξηγεί γιατί χρειάζονται τα δεδομένα και πώς υποστηρίζει τη συνδημιουργία.',
  'privacy.helpTitle': 'Χρειάζεστε βοήθεια με ένα αίτημα απορρήτου;',
  'privacy.helpText': 'Επικοινωνήστε με τον πιλοτικό συντονιστή ή την επαφή του έργου SPICE με τη διεύθυνση email που χρησιμοποιείται για τον λογαριασμό σας, τον πιλοτικό σας ιστότοπο και τον τύπο αιτήματος. Το αίτημα θα δρομολογηθεί στον κατάλληλο υπεύθυνο οργανισμό.',
  'privacy.section.overview.title': 'Επισκόπηση απορρήτου',
  'privacy.section.overview.text': 'Το SPICE υποστηρίζει τη συν-δημιουργία χωρίς αποκλεισμούς σε δημόσιο χώρο, ενώ περιορίζει τη συλλογή προσωπικών δεδομένων σε ό,τι απαιτείται για τη συμμετοχή, την ασφάλεια και την αναφορά έργου.',
  'privacy.section.collection.title': 'Προσωπικά δεδομένα που συλλέγουμε',
  'privacy.section.collection.text': 'Ενδέχεται να συλλέξουμε στοιχεία λογαριασμού, συνεργασία πιλότου, προτιμήσεις γλώσσας και προσβασιμότητας, συμμετοχή, σχόλια χάρτη, ψήφους, μεταφορτωμένα μέσα, σχόλια και τεχνικές πληροφορίες χρήσης.',
  'privacy.section.use.title': 'Πώς χρησιμοποιούμε προσωπικά δεδομένα',
  'privacy.section.use.text': 'Τα δεδομένα χρησιμοποιούνται για τη λειτουργία της πλατφόρμας, την υποστήριξη της συμμετοχής, την παραγωγή αποτελεσμάτων συν-δημιουργίας, τη βελτίωση της προσβασιμότητας, την πρόληψη της κακής χρήσης και την παροχή δομημένων, συγκεντρωτικών πληροφοριών.',
  'privacy.section.sharing.title': 'Συνεργάτες κοινής χρήσης και έργου',
  'privacy.section.sharing.text': 'Σχετικά δεδομένα του έργου ενδέχεται να κοινοποιηθούν σε εξουσιοδοτημένους εταίρους SPICE, πιλοτικούς δήμους, διαμεσολαβητές και τεχνικούς παρόχους όπου είναι απαραίτητο για τη διαδικασία συνδημιουργίας.',
  'privacy.section.cookies.title': 'Cookies και παρόμοιες τεχνολογίες',
  'privacy.section.cookies.text': 'Τα βασικά cookie διατηρούν την εργαλειοθήκη ασφαλή και λειτουργική. Τα προαιρετικά cookie αναλυτικών στοιχείων συμβάλλουν στη βελτίωση των ροών εργασίας, της απόδοσης, της πολυγλωσσικής υποστήριξης και της προσβασιμότητας.',
  'privacy.section.rights.title': 'Τα δικαιώματα απορρήτου σας',
  'privacy.section.rights.text': 'Ανάλογα με την τοποθεσία σας, μπορείτε να ζητήσετε πρόσβαση, διόρθωση, διαγραφή, περιορισμό, φορητότητα ή αντίρρηση στην επεξεργασία των προσωπικών σας δεδομένων.',
  'privacy.section.security.title': 'Προστασία προσωπικών δεδομένων',
  'privacy.section.security.text': 'Το SPICE χρησιμοποιεί πρόσβαση βάσει ρόλων, ασφαλείς λειτουργίες, ελαχιστοποίηση δεδομένων και πρακτικές υπεύθυνης διατήρησης για την προστασία των συνεισφορών των συμμετεχόντων.',
  'privacy.section.contact.title': 'Ερωτήσεις απορρήτου',
  'privacy.section.contact.text': 'Για ερωτήσεις ή αιτήματα απορρήτου, επικοινωνήστε με την ομάδα του έργου SPICE ή τον υπεύθυνο πιλοτικό οργανισμό που αναφέρεται στο τοπικό υλικό συμμετοχής σας.',
  'guide.title': 'Οδηγός συν-δημιουργίας',
  'guide.subtitle': 'Καθοδηγούμενη υποστήριξη για την επιλογή εργαλείων και τη δομή της διαδικασίας',
  'guide.mode.guided': 'Καθοδηγούμενη',
  'guide.mode.exploratory': 'Εξερευνητικό',
  'guide.mode.factual': 'Πραγματικό',
  'guide.initialMessage': 'Γεια σας! Είμαι ο SPICE Co-Creation Agent. Μπορώ να σας βοηθήσω να επιλέξετε εργαλεία, να κατανοήσετε τις μεθόδους συνδημιουργίας και να δομήσετε τη συμμετοχική σας διαδικασία.\n\nΟι απαντήσεις μου χρησιμοποιούν τεκμηρίωση εργαλειοθήκης SPICE, πιλοτικά διαγνωστικά και πηγές αποθετηρίου.\n\nΠώς μπορώ να σας βοηθήσω σήμερα;',
  'guide.prompt.tools': 'Ποια εργαλεία ταιριάζουν σε ένα εργαστήριο για συλλογική κατανόηση;',
  'guide.prompt.difference': 'Εξηγήστε τη διαφορά μεταξύ συν-σχεδιασμού και συμβουλευτικής.',
  'guide.prompt.summary': 'Συνοψίστε την επιλεγμένη διαδικασία για το πιλότο Θεσσαλονίκης.',
  'guide.prompt.collective': 'Ποια εργαλεία υποστηρίζουν τη συλλογική κατανόηση;',
  'guide.reply': 'Χρησιμοποιώντας τις πηγές της εργαλειοθήκης SPICE, μπορώ να βοηθήσω με το "{{question}}". Για τη Φάση 3, σκεφτείτε ένα εργαστήριο μελλοντικών σεναρίων για συλλογικό οραματισμό. Θα θέλατε μια επεξήγηση μεθοδολογίας ή υποστηρικτικά εργαλεία;',
  'guide.justNow': 'Μόλις τώρα',
