  'guide.source.aiText': 'Οι απαντήσεις χρησιμοποιούν επαυξημένη παραγωγή ανάκτησης μόνο μέσω της τεκμηρίωσης του έργου SPICE. Δεν χρησιμοποιείται εξωτερική πρόσβαση στο Διαδίκτυο.',

