  'chatbot.article.section1.title': 'Τι είναι το SPICE;',
  'chatbot.article.section1.text': 'Το SPICE είναι ένα έργο που χρηματοδοτείται από την ΕΕ που βοηθά τους πολίτες, τις κοινότητες, τους σχεδιαστές, τους δήμους και τους εταίρους του έργου να συνεργαστούν για να διαμορφώσουν καλύτερους δημόσιους χώρους.',
  'chatbot.article.section2.title': 'Γιατί δημιουργήθηκε το SPICE;',
  'chatbot.article.section2.text': 'Οι δημόσιοι χώροι διαμορφώνουν την καθημερινότητα. Τα πάρκα, οι δρόμοι, οι πλατείες, οι προκυμαίες και οι κοινοτικές περιοχές επηρεάζουν τον τρόπο με τον οποίο οι άνθρωποι μετακινούνται, συναντιούνται, αισθάνονται ασφαλείς και ανήκουν.',
  'chatbot.article.section3.title': 'Τι κάνει το SPICE Digital Toolkit;',
  'chatbot.article.section3.text': 'Η εργαλειοθήκη συγκεντρώνει καθοδήγηση για συνδημιουργία, σχόλια, χάρτες, σενάρια, ψηφοφορία, πόρους και ενημερώσεις έργων σε ένα μέρος.',
  'chatbot.article.section4.title': 'Για ποιον απευθύνεται το SPICE;',
  'chatbot.article.section4.text': 'Το SPICE υποστηρίζει πολίτες, τοπικές κοινότητες, δήμους, διευκολυντές, ερευνητές και τοπικούς ενδιαφερόμενους φορείς που εμπλέκονται στη βελτίωση των δημόσιων χώρων.',
  'chatbot.article.section5.title': 'Πώς λειτουργεί η συμμετοχή;',
  'chatbot.article.section5.text': 'Ανάλογα με τον πιλότο, μπορείτε να σχολιάσετε έναν δημόσιο χώρο, να επισημάνετε ιδέες σε έναν χάρτη, να συγκρίνετε σενάρια, να ψηφίσετε προτάσεις ή να συμμετάσχετε σε εργαστήρια.',
  'chatbot.article.section6.title': 'Τι μπορείτε να κάνετε στη συνέχεια;',
  'chatbot.article.section6.text': 'Εξερευνήστε τον πιλότο σας, μάθετε για τη διαδικασία συνδημιουργίας ή χρησιμοποιήστε τα εργαλεία SPICE για να κάνετε την πρώτη σας συνεισφορά.',
  'chatbot.intro': 'Γεια σας, είμαι ο Βοηθός SPICE. Μπορώ να σας βοηθήσω να κατανοήσετε το έργο, να εξερευνήσετε την εργαλειοθήκη και να βρείτε καθοδήγηση για τη συμμετοχή στο τοπικό πιλοτικό σας πρόγραμμα.',
  'chatbot.reply': 'Ευχαριστούμε. Μπορώ να συνδέσω αυτήν την ερώτηση με τη σχετική μέθοδο SPICE, το πιλοτικό πλαίσιο και την επόμενη ενέργεια. Μπορείτε επίσης να ανοίξετε τη Βοήθεια για τον οδηγό δομημένου έργου.',

