  'demo.facilitator.toolsTitle': 'Συνδέστε εργαλεία με τη δραστηριότητα',
  'demo.facilitator.toolsText': 'Συνδέστε εργαλεία καταλόγου με τη δραστηριότητα και εξηγήστε τι θα κάνουν οι συμμετέχοντες. Η γενική καθοδήγηση εργαλείου διαφέρει από τις ειδικές οδηγίες της δραστηριότητας.',
  'demo.facilitator.resultsTitle': 'Μεταφορτώστε αποτελέσματα φάσης',
