  'privacy.title': 'Tietosuojakäytäntö',
  'privacy.updated': 'Päivitetty 7. heinäkuuta 2026',
  'privacy.intro': 'Tämä tietosuojakäytäntö selittää, kuinka SPICE Digital Toolkit kerää, käyttää, jakaa ja suojaa henkilötietoja, kun kansalaiset, kunnat, fasilitaattorit ja projektikumppanit käyttävät alustaa.',
  'privacy.contextNotice': 'SPICE voi myös näyttää asiayhteyteen liittyviä tietosuojailmoituksia tietyissä työkaluissa ja tiliasetuksissa, jotta ihmiset ymmärtävät, mitä tietoja pyydetään, ennen kuin he osallistuvat.',
  'privacy.readPolicy': 'Lue käytäntö',
  'privacy.download': 'Lataa kopio',
  'privacy.cookiePreferences': 'Evästeasetukset',
  'privacy.dataPrivacy': 'Tiedot ja tietosuoja',
  'privacy.participantFirst': 'Osallistuja ensin',
  'privacy.participantFirstText': 'Työkalusarja tukee kansalaisten osallistumista. Avustuksia käsitellään kunnioittavasti, läpinäkyvästi ja selkeällä, rajoitetulla tarkoituksella.',
  'privacy.policyHeadings': 'Käytäntöotsikot',
  'privacy.contextualText': 'SPICE pitää tietosuojatiedot käytännöllisinä ja asiayhteyteen perustuvina. Kun työkalu pyytää panosta, latausta, sijaintia tai tilitoimintoa, se selittää, miksi tietoja tarvitaan ja miten se tukee yhteisluomista.',
  'privacy.helpTitle': 'Tarvitsetko apua tietosuojapyynnössä?',
  'privacy.helpText': 'Ota yhteyttä pilottivastaavaan tai SPICE-projektin yhteyshenkilöön ja kerro tilissäsi käytetty sähköpostiosoite, pilottisivustosi ja pyyntötyyppi. Pyyntö välitetään asianmukaiselle vastuussa olevalle organisaatiolle.',
  'privacy.section.overview.title': 'Yksityisyyden yleiskatsaus',
  'privacy.section.overview.text': 'SPICE tukee osallistavaa julkisen tilan yhteisluomista ja rajoittaa henkilötietojen keräämisen siihen, mitä tarvitaan osallistumiseen, turvallisuuteen ja projektiraportointiin.',
  'privacy.section.collection.title': 'Keräämämme henkilötiedot',
  'privacy.section.collection.text': 'Saamme kerätä tilitietoja, pilottijäsenyyttä, kieli- ja esteettömyysasetuksia, osallistumista, karttapalautetta, ääniä, ladattua mediaa, kommentteja ja teknisiä käyttötietoja.',
  'privacy.section.use.title': 'Miten käytämme henkilötietoja',
  'privacy.section.use.text': 'Tietoja käytetään alustan toimintaan, osallistumisen tukemiseen, yhteistuotannon tuottamiseen, saavutettavuuden parantamiseen, väärinkäytösten estämiseen ja jäsenneltyjen, koottujen näkemysten tarjoamiseen.',
  'privacy.section.sharing.title': 'Jakamis- ja projektikumppanit',
  'privacy.section.sharing.text': 'Projektitiedot voidaan jakaa valtuutettujen SPICE-kumppaneiden, pilottikuntien, fasilitaattoreiden ja teknisten tarjoajien kanssa, jos se on tarpeen yhteisluontiprosessia varten.',
  'privacy.section.cookies.title': 'Evästeet ja vastaavat tekniikat',
  'privacy.section.cookies.text': 'Tärkeät evästeet pitävät työkalupakin turvallisena ja toimivana. Valinnaiset analytiikkaevästeet auttavat parantamaan työnkulkua, suorituskykyä, monikielistä tukea ja saavutettavuutta.',
  'privacy.section.rights.title': 'Tietosuojaoikeutesi',
  'privacy.section.rights.text': 'Sijainnistasi riippuen voit pyytää pääsyä, oikaisua, poistamista, rajoittamista, siirrettävyyttä tai vastustaa henkilötietojesi käsittelyä.',
  'privacy.section.security.title': 'Henkilötietojen suojaaminen',
  'privacy.section.security.text': 'SPICE käyttää roolipohjaisia ​​käyttöoikeuksia, suojattuja toimintoja, tietojen minimointia ja vastuullisia säilytyskäytäntöjä osallistujien lahjoitusten suojaamiseksi.',
  'privacy.section.contact.title': 'Tietosuojakysymykset',
  'privacy.section.contact.text': 'Jos sinulla on tietosuojakysymyksiä tai pyyntöjä, ota yhteyttä SPICE-projektitiimiin tai vastaavaan pilottiorganisaatioon, joka on lueteltu paikallisissa osallistumismateriaaleissasi.',
