  'chatbot.collection.start.text': 'Tutustu projektiin, tutustu tapoihin osallistua ja ymmärrä, kuinka panoksesi auttaa muokkaamaan parempia julkisia tiloja.',
  'chatbot.collection.toolkit.title': 'Työkalupakin käyttäminen',
  'chatbot.collection.toolkit.text': 'Käytännön ohjeita CitiVoicen, 3D Scene Editorin, tekoälytuen, palauteominaisuuksien ja osallistumistoimintojen käyttöön.',
