  'chatbot.article.back': 'Takaisin artikkeleihin',
  'chatbot.article.section1.title': 'Mikä on SPICE?',
  'chatbot.article.section1.text': 'SPICE on EU:n rahoittama hanke, joka auttaa kansalaisia, yhteisöjä, suunnittelijoita, kuntia ja hankekumppaneita työskentelemään yhdessä paremman julkisen tilan muokkaamiseksi.',
  'chatbot.article.section2.title': 'Miksi SPICE luotiin?',
  'chatbot.article.section2.text': 'Julkiset tilat muokkaavat arkea. Puistot, kadut, aukiot, ranta-alueet ja yhteisön alueet vaikuttavat siihen, miten ihmiset liikkuvat, tapaavat, tuntevat olonsa turvalliseksi ja kuuluvat yhteen.',
  'chatbot.article.section3.title': 'Mitä SPICE Digital Toolkit tekee?',
  'chatbot.article.section3.text': 'Työkalupakki tuo yhteen paikkaan yhteisluontiohjeet, palautteen, kartat, skenaariot, äänestykset, resurssit ja projektipäivitykset.',
  'chatbot.article.section4.title': 'Kenelle SPICE on tarkoitettu?',
  'chatbot.article.section4.text': 'SPICE tukee kansalaisia, paikallisyhteisöjä, kuntia, fasilitaattoreita, tutkijoita ja paikallisia sidosryhmiä, jotka ovat mukana julkisten tilojen parantamisessa.',
  'chatbot.article.section5.title': 'Miten osallistuminen toimii?',
  'chatbot.article.section5.text': 'Pilotista riippuen voit kommentoida julkista tilaa, merkitä ideoita kartalle, vertailla skenaarioita, äänestää ehdotuksista tai osallistua työpajoihin.',
  'chatbot.article.section6.title': 'Mitä voit tehdä seuraavaksi?',
  'chatbot.article.section6.text': 'Tutustu pilottiisi, opi yhteisluontiprosessista tai anna ensimmäinen panoksesi SPICE-työkalujen avulla.',
  'chatbot.intro': 'Hei, olen SPICE-assistentti. Voin auttaa sinua ymmärtämään projektin, tutkimaan työkalupakkia ja löytämään ohjeita paikalliseen pilottiprojektiin osallistumiseen.',
  'chatbot.reply': 'Kiitos. Voin yhdistää tämän kysymyksen asiaankuuluvaan SPICE-menetelmään, pilottikontekstiin ja seuraavaan toimintoon. Voit myös avata jäsennellyn projektioppaan Ohjeen.',

