  'home.tool.repositoryText': 'Uzyskuj dostęp do dokumentów pilotażowych, wyników warsztatów, raportów, multimediów, szablonów i wyników współtworzenia w jednej zorganizowanej przestrzeni.',
  'home.tool.forumText': 'Omawiaj pomysły, wymieniaj perspektywy, komentuj propozycje oraz bierz udział w ankietach i głosowaniach.',
  'home.tool.insightsText': 'Śledź udział, wzorce opinii, wyniki i postęp pilotażu.',
  'home.feature.localized': 'Zlokalizowany interfejs',
  'home.feature.localizedText': 'Nawigacja, formularze, instrukcje i powiadomienia dostosowane do każdego języka pilotażowego.',
  'home.feature.guidance': 'Przejrzyste wskazówki',
  'home.feature.guidanceText': 'Krótkie wyjaśnienia i pomoc krok po kroku dla początkujących i nieekspertów.',
  'home.feature.participation': 'Włączające uczestnictwo',
  'home.feature.participationText': 'Uczestnicy mogą rozumieć, wnosić swój wkład, głosować i śledzić wyniki w znanym im języku.',
  'home.feature.content': 'Treść gotowa do pilotażu',
  'home.feature.contentText': 'Strony projektów, formularze opinii, podsumowania i materiały można zlokalizować dla każdego miasta.',
  'hub.eyebrow': 'Cyfrowy zestaw narzędzi SPICE',
  'hub.title': 'Centrum współtworzenia',
  'hub.subtitle': 'Weź udział w lokalnych witrynach pilotażowych dotyczących współtworzenia, weź udział w otwartych działaniach i śledź, jak wkład społeczności wpływa na decyzje dotyczące przestrzeni publicznej.',
  'hub.subtitleCitizen': 'Weź udział w lokalnych witrynach pilotażowych dotyczących współtworzenia, weź udział w otwartych działaniach i śledź, jak wkład społeczności wpływa na decyzje dotyczące przestrzeni publicznej.',
  'hub.subtitleMunicipality': 'Zarządzaj fazami, narzędziami i uczestnictwem w witrynie pilotażowej oraz przeglądaj wkłady obywateli.',
  'hub.subtitleFacilitator': 'Wspieraj przydzielony ośrodek pilotażowy: przygotuj działania, prześlij wyniki warsztatów i projekty wniosków do przeglądu przez władze lokalne.',
  'hub.subtitleAdmin': 'Przejrzyj każdą pilotażową witrynę współtworzenia na platformie i otwórz obszar administracyjny dla użytkowników, ról i działań audytowych.',
  'hub.phase1': 'Kadrowanie i gotowość',
  'hub.phase1Text': 'Zapoznaj się z witryną pilotażową, zakresem uczestnictwa, celami i sposobem działania procesu współtworzenia.',
  'hub.phase2': 'Wspólne zrozumienie',
  'hub.phase2Text': 'Poznaj lokalne potrzeby, doświadczenia, dowody i priorytety społeczności.',
  'hub.phase3': 'Współprojektowanie i tworzenie scenariuszy',
