  // Generated baseline; canonical SPICE terminology is reviewed below through explicit overrides.
  'privacy.languageLabel': 'Język zasad',
  'privacy.eyebrow': 'Zaufanie i przejrzystość',
  'privacy.title': 'Polityka prywatności',
  'privacy.updated': 'Zaktualizowano 7 lipca 2026 r.',
  'privacy.intro': 'Niniejsza Polityka prywatności wyjaśnia, w jaki sposób zestaw narzędzi cyfrowych SPICE gromadzi, wykorzystuje, udostępnia i chroni dane osobowe, gdy z platformy korzystają obywatele, gminy, koordynatorzy i partnerzy projektu.',
  'privacy.contextNotice': 'SPICE może także wyświetlać kontekstowe informacje o ochronie prywatności w określonych narzędziach i ustawieniach konta, aby użytkownicy wiedzieli, jakie dane są wymagane, zanim je udostępnią.',
  'privacy.readPolicy': 'Przeczytaj zasady',
  'privacy.download': 'Pobierz kopię',
  'privacy.cookiePreferences': 'Preferencje dotyczące plików cookie',
  'privacy.dataPrivacy': 'Dane i prywatność',
  'privacy.participantFirst': 'Najpierw uczestnik',
  'privacy.participantFirstText': 'Zestaw narzędzi wspiera aktywność obywatelską. Wkłady są traktowane z szacunkiem, przejrzystością i mają jasny, ograniczony cel.',
  'privacy.policyHeadings': 'Nagłówki zasad',
  'privacy.contextualText': 'SPICE zapewnia praktyczne i kontekstowe informacje dotyczące prywatności. Gdy narzędzie żąda wkładu, przesłania, lokalizacji lub działania na koncie, wyjaśnia, dlaczego dane są potrzebne i jak wspiera współtworzenie.',
  'privacy.helpTitle': 'Potrzebujesz pomocy w związku z prośbą o ochronę prywatności?',
  'privacy.helpText': 'Skontaktuj się ze swoim koordynatorem projektu pilotażowego lub osobą kontaktową ds. projektu SPICE, podając adres e-mail używany na Twoim koncie, witrynę pilotażową i typ prośby. Wniosek zostanie przekazany do odpowiedniej odpowiedzialnej organizacji.',
  'privacy.section.overview.title': 'Przegląd prywatności',
  'privacy.section.overview.text': 'SPICE wspiera włączające współtworzenie przestrzeni publicznej, ograniczając jednocześnie gromadzenie danych osobowych do tego, co jest potrzebne do uczestnictwa, bezpieczeństwa i raportowania projektu.',
  'privacy.section.collection.title': 'Dane osobowe, które gromadzimy',
  'privacy.section.collection.text': 'Możemy zbierać dane konta, przynależność pilotażową, preferencje językowe i dostępność, uczestnictwo, opinie o mapach, głosy, przesłane multimedia, komentarze i informacje o użytkowaniu technicznym.',
  'privacy.section.use.title': 'Jak wykorzystujemy dane osobowe',
  'privacy.section.use.text': 'Dane służą do obsługi platformy, wspierania uczestnictwa, tworzenia wyników wspólnego tworzenia, poprawiania dostępności, zapobiegania nadużyciom i zapewniania uporządkowanych, zagregowanych spostrzeżeń.',
  'privacy.section.sharing.title': 'Udostępnianie i partnerzy projektu',
  'privacy.section.sharing.text': 'Istotne dane projektu mogą być udostępniane autoryzowanym partnerom SPICE, gminom pilotażowym, koordynatorom i dostawcom technologii, jeśli jest to konieczne do procesu współtworzenia.',
  'privacy.section.cookies.title': 'Pliki cookie i podobne technologie',
  'privacy.section.cookies.text': 'Niezbędne pliki cookie zapewniają bezpieczeństwo i funkcjonalność zestawu narzędzi. Opcjonalne analityczne pliki cookie pomagają usprawnić przepływ pracy, wydajność, obsługę wielojęzyczną i dostępność.',
  'privacy.section.rights.title': 'Twoje prawa do prywatności',
  'privacy.section.rights.text': 'W zależności od Twojej lokalizacji możesz poprosić o dostęp, poprawienie, usunięcie, ograniczenie, przenoszenie lub sprzeciwić się przetwarzaniu Twoich danych osobowych.',
  'privacy.section.security.title': 'Ochrona danych osobowych',
  'privacy.section.security.text': 'SPICE wykorzystuje dostęp oparty na rolach, bezpieczne operacje, minimalizację danych i praktyki odpowiedzialnego przechowywania, aby chronić wkład uczestników.',
  'privacy.section.contact.title': 'Pytania dotyczące prywatności',
  'privacy.section.contact.text': 'W przypadku pytań lub próśb dotyczących prywatności skontaktuj się z zespołem projektowym SPICE lub odpowiedzialną organizacją pilotażową wymienioną w lokalnych materiałach dotyczących uczestnictwa.',
  'guide.title': 'Przewodnik wspólnego tworzenia',
  'guide.subtitle': 'Wsparcie w zakresie wyboru narzędzi i strukturyzowania procesu',
  'guide.mode.guided': 'Z przewodnikiem',
  'guide.mode.exploratory': 'Odkrywcze',
  'guide.mode.factual': 'Fakty',
  'guide.initialMessage': 'Witam! Jestem agentem współtworzącym SPICE. Pomogę Ci wybrać narzędzia, zrozumieć metody współtworzenia i ustrukturyzować proces partycypacyjny.\n\nW moich odpowiedziach korzystam z dokumentacji zestawu narzędzi SPICE, diagnostyki pilotażowej i źródeł repozytoriów.\n\nJak mogę Ci dzisiaj pomóc?',
  'guide.prompt.tools': 'Jakie narzędzia pasują do warsztatu wspólnego zrozumienia?',
  'guide.prompt.difference': 'Wyjaśnij różnicę między współprojektowaniem a konsultacją.',
  'guide.prompt.summary': 'Podsumuj wybrany proces pilotażowy w Salonikach.',
