  'guide.reply': 'Korzystając ze źródeł zestawu narzędzi SPICE, mogę pomóc w zadaniu „{{question}}”. W fazie 3 rozważ warsztaty dotyczące scenariuszy przyszłości w zakresie zbiorowej wizji. Czy potrzebujesz wyjaśnienia metodologii lub narzędzi pomocniczych?',
