  'chatbot.collection.start.title': 'Pierwsze kroki',
  'chatbot.collection.start.text': 'Odkryj projekt, poznaj sposoby uczestnictwa i dowiedz się, jak Twój wkład pomaga kształtować lepsze przestrzenie publiczne.',
  'chatbot.collection.toolkit.title': 'Korzystanie z zestawu narzędzi',
  'chatbot.collection.toolkit.text': 'Praktyczne wskazówki dotyczące korzystania z CitiVoice, edytora scen 3D, obsługi sztucznej inteligencji, funkcji przesyłania opinii i działań partycypacyjnych.',
  'chatbot.collection.trouble.title': 'Pomoc i rozwiązywanie problemów',
  'chatbot.collection.trouble.text': 'Znajdź rozwiązania typowych pytań technicznych, dostępu do konta i kluczowych zadań.',
  'chatbot.collection.pilots.title': 'Piloci i społeczność',
  'chatbot.collection.pilots.text': 'Dowiedz się o lokalnych działaniach, warsztatach i współpracy społeczności i gmin w SPICE.',
  'chatbot.article.what': 'Co to jest projekt SPICE?',
  'chatbot.article.participate': 'Jak mogę wziąć udział?',
  'chatbot.article.after': 'Co się stanie, gdy przekażę swój wkład?',
  'chatbot.articleLabel': 'Artykuł pomocy',
  'chatbot.article.author': 'Napisane przez zespół SPICE',
  'chatbot.article.date': '17 czerwca 2026',
  'chatbot.article.backHelp': 'Wróć do pomocy',
  'chatbot.article.expand': 'Rozwiń artykuł',
  'chatbot.article.shrink': 'Zmniejsz artykuł',
  'chatbot.article.return': 'Wróć do rozmowy',
  'chatbot.article.back': 'Powrót do artykułów',
  'chatbot.article.section1.title': 'Co to jest SPICE?',
  'chatbot.article.section1.text': 'SPICE to projekt finansowany ze środków UE, który pomaga obywatelom, społecznościom, planistom, gminom i partnerom projektu współpracować na rzecz kształtowania lepszych przestrzeni publicznych.',
  'chatbot.article.section2.title': 'Dlaczego powstał SPICE?',
  'chatbot.article.section2.text': 'Przestrzenie publiczne kształtują codzienne życie. Parki, ulice, place, nabrzeża i obszary społeczne wpływają na to, jak ludzie się poruszają, spotykają, czują się bezpiecznie i przynależą.',
  'chatbot.article.section3.title': 'Do czego służy cyfrowy zestaw narzędzi SPICE?',
  'chatbot.article.section3.text': 'Zestaw narzędzi zapewnia w jednym miejscu wskazówki dotyczące współtworzenia, opinie, mapy, scenariusze, głosowanie, zasoby i aktualizacje projektu.',
  'chatbot.article.section4.title': 'Dla kogo jest SPICE?',
  'chatbot.article.section4.text': 'SPICE wspiera obywateli, społeczności lokalne, gminy, moderatorów, badaczy i lokalne zainteresowane strony zaangażowane w poprawę przestrzeni publicznej.',
  'chatbot.article.section5.title': 'Jak działa uczestnictwo?',
  'chatbot.article.section5.text': 'W zależności od pilota możesz komentować przestrzeń publiczną, zaznaczać pomysły na mapie, porównywać scenariusze, głosować na propozycje lub dołączać do warsztatów.',
  'chatbot.article.section6.title': 'Co możesz dalej zrobić?',
  'chatbot.article.section6.text': 'Odkryj swój projekt pilotażowy, poznaj proces współtworzenia lub skorzystaj z narzędzi SPICE, aby wnieść swój pierwszy wkład.',
  'chatbot.intro': 'Witam, jestem Asystentem SPICE. Mogę pomóc Ci zrozumieć projekt, zapoznać się z zestawem narzędzi i znaleźć wskazówki dotyczące udziału w lokalnym programie pilotażowym.',
  'chatbot.reply': 'Dziękuję. Mogę powiązać to pytanie z odpowiednią metodą SPICE, kontekstem pilotażowym i następnym działaniem. Możesz także otworzyć Pomoc dla zorganizowanego przewodnika po projekcie.',

