  // Generated baseline; canonical SPICE terminology is reviewed below through explicit overrides.
  'privacy.languageLabel': 'Linguagem da política',
  'privacy.eyebrow': 'Confiança e transparência',
  'privacy.title': 'Política de Privacidade',
  'privacy.updated': 'Atualizado a 7 de julho de 2026',
  'privacy.intro': 'Esta Política de Privacidade explica como o SPICE Digital Toolkit recolhe, utiliza, partilha e protege dados pessoais quando os cidadãos, municípios, facilitadores e parceiros de projetos utilizam a plataforma.',
  'privacy.contextNotice': 'O SPICE também pode mostrar avisos contextuais de privacidade em ferramentas e definições de conta específicas, para que as pessoas compreendam que dados são solicitados antes de contribuírem.',
  'privacy.readPolicy': 'Leia a política',
  'privacy.download': 'Descarregue uma cópia',
  'privacy.cookiePreferences': 'Preferências de cookies',
  'privacy.dataPrivacy': 'Dados e privacidade',
  'privacy.participantFirst': 'Primeiro o participante',
  'privacy.participantFirstText': 'O kit de ferramentas apoia a participação cívica. As contribuições são tratadas com respeito, transparência e um propósito claro e limitado.',
  'privacy.policyHeadings': 'Títulos da política',
  'privacy.contextualText': 'O SPICE mantém as informações de privacidade práticas e contextuais. Quando uma ferramenta solicita uma contribuição, upload, localização ou ação da conta, explica porque é que os dados são necessários e como apoiam a cocriação.',
  'privacy.helpTitle': 'Precisa de ajuda com um pedido de privacidade?',
  'privacy.helpText': 'Contacte o seu facilitador piloto ou o contacto do projeto SPICE com o endereço de e-mail utilizado para a sua conta, o seu site piloto e o tipo de pedido. O pedido será encaminhado para a organização responsável apropriada.',
  'privacy.section.overview.title': 'Visão geral da privacidade',
  'privacy.section.overview.text': 'O SPICE apoia a cocriação inclusiva em espaços públicos, ao mesmo tempo que limita a recolha de dados pessoais ao que é necessário para a participação, segurança e relatórios de projetos.',
  'privacy.section.collection.title': 'Dados pessoais que recolhemos',
  'privacy.section.collection.text': 'Podemos recolher detalhes da conta, afiliação do piloto, preferências de idioma e acessibilidade, participação, feedback do mapa, votos, meios enviados, comentários e informações técnicas de utilização.',
  'privacy.section.use.title': 'Como utilizamos os dados pessoais',
  'privacy.section.use.text': 'Os dados são utilizados para operar a plataforma, apoiar a participação, produzir resultados de cocriação, melhorar a acessibilidade, evitar o uso indevido e fornecer insights estruturados e agregados.',
  'privacy.section.sharing.title': 'Partilha e parceiros de projeto',
  'privacy.section.sharing.text': 'Os dados relevantes do projeto podem ser partilhados com os parceiros autorizados do SPICE, municípios piloto, facilitadores e fornecedores técnicos quando necessário para o processo de cocriação.',
  'privacy.section.cookies.title': 'Cookies e tecnologias semelhantes',
  'privacy.section.cookies.text': 'Os cookies essenciais mantêm o kit de ferramentas seguro e funcional. Os cookies analíticos opcionais ajudam a melhorar os fluxos de trabalho, o desempenho, o suporte multilingue e a acessibilidade.',
  'privacy.section.rights.title': 'Os seus direitos de privacidade',
  'privacy.section.rights.text': 'Dependendo da sua localização, pode solicitar o acesso, correção, eliminação, restrição, portabilidade ou opor-se ao tratamento dos seus dados pessoais.',
  'privacy.section.security.title': 'Protecção de dados pessoais',
  'privacy.section.security.text': 'O SPICE utiliza o acesso baseado em funções, operações seguras, minimização de dados e práticas de retenção responsáveis ​​para proteger as contribuições dos participantes.',
  'privacy.section.contact.title': 'Questões sobre privacidade',
  'privacy.section.contact.text': 'Para questões ou pedidos de privacidade, por favor contacte a equipa do projeto SPICE ou a organização piloto responsável listada nos seus materiais de participação locais.',
