  'chatbot.article.return': 'Voltar à conversa',
  'chatbot.article.back': 'Voltar aos artigos',
  'chatbot.article.section1.title': 'O que é o SPICE?',
  'chatbot.article.section1.text': 'O SPICE é um projeto financiado pela UE que ajuda os cidadãos, as comunidades, os planeadores, os municípios e os parceiros de projeto a trabalharem em conjunto para moldar melhores espaços públicos.',
  'chatbot.article.section2.title': 'Porque foi criado o SPICE?',
  'chatbot.article.section2.text': 'Os espaços públicos moldam o quotidiano. Parques, ruas, praças, frentes de água e áreas comunitárias influenciam a forma como as pessoas se movimentam, se encontram, se sentem seguras e pertencem.',
  'chatbot.article.section3.title': 'O que faz o SPICE Digital Toolkit?',
  'chatbot.article.section3.text': 'O kit de ferramentas reúne orientações de cocriação, feedback, mapas, cenários, votação, recursos e atualizações de projetos num único local.',
  'chatbot.article.section4.title': 'Para quem é o SPICE?',
  'chatbot.article.section4.text': 'O SPICE apoia os cidadãos, as comunidades locais, os municípios, os facilitadores, os investigadores e as partes interessadas locais envolvidas na melhoria dos espaços públicos.',
  'chatbot.article.section5.title': 'Como funciona a participação?',
  'chatbot.article.section5.text': 'Dependendo do piloto, pode comentar num espaço público, assinalar ideias num mapa, comparar cenários, votar propostas ou participar em workshops.',
  'chatbot.article.section6.title': 'O que pode fazer a seguir?',
  'chatbot.article.section6.text': 'Explore o seu piloto, aprenda sobre o processo de cocriação ou utilize as ferramentas SPICE para fazer a sua primeira contribuição.',
  'chatbot.intro': 'Olá, sou o assistente do SPICE. Posso ajudá-lo a compreender o projeto, explorar o kit de ferramentas e encontrar orientação para participar no piloto local.',
  'chatbot.reply': 'Obrigado. Posso ligar esta questão ao método SPICE relevante, ao contexto piloto e à próxima ação. Também pode abrir a Ajuda para obter o guia estruturado do projeto.',

